  (["localhost", "127.0.0.1"].includes(location.hostname)
    ? "http://localhost:8000"
    : "https://boombastic-crm-api.vercel.app");
const app = document.querySelector("#app"), toast = document.querySelector("#toast");
const state = {token: localStorage.getItem("crm_token"), user: JSON.parse(localStorage.getItem("crm_user") || '{"name":"Demo User","role":"admin"}'), view:"leads", leadView:localStorage.getItem("crm_lead_view")||(matchMedia("(max-width: 760px)").matches?"cards":"table"), bookingView:localStorage.getItem("crm_booking_view")||"calendar", bookingMonth:new Date().getMonth(), bookingYear:new Date().getFullYear(), dashboardPeriod:localStorage.getItem("crm_dashboard_period")||"This Month", dashboardFrom:localStorage.getItem("crm_dashboard_from")||"", dashboardTo:localStorage.getItem("crm_dashboard_to")||"", reportPeriod:localStorage.getItem("crm_report_period")||"This Month", reportFrom:localStorage.getItem("crm_report_from")||"", reportTo:localStorage.getItem("crm_report_to")||"", leads:[], filters:{q:"",source:"",status:"",follow_up:""}, timer:null};
const nav = [["dashboard","▧","Dashboard"],["leads","♙","Leads"],["followups","◷","Follow-ups"],["bookings","▣","Bookings"],["reports","▥","Reports"],["agreements","⚙","Settings"]];
const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const money = v => "₹" + Number(v || 0).toLocaleString("en-IN");
const nice = v => String(v || "").replaceAll("_"," ").replace(/\b\w/g, c => c.toUpperCase());
const initials = name => (name || "?").split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase();
function say(message){toast.textContent=message;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),2600)}
function apiMessage(payload){
  const detail=payload?.detail;
  if(Array.isArray(detail))return detail.map(x=>`${(x.loc||[]).slice(1).join(".")||"Request"}: ${x.msg||"Invalid value"}`).join(" · ");
  if(typeof detail==="object"&&detail)return detail.message||JSON.stringify(detail);
  return detail||"Request failed";
}
async function api(path, options={}) {
  const headers = {...(options.body ? {"Content-Type":"application/json"} : {}), ...(state.token ? {Authorization:"Bearer "+state.token}:{})};
  const r = await fetch(API + path, {...options,headers:{...headers,...options.headers}});
  if (r.status===401) {logout(); throw new Error("Please sign in again");}
  if (!r.ok) throw new Error(apiMessage(await r.json().catch(()=>({detail:"Request failed"}))));
  return r.status===204 ? null : r.json();
}
function shell(content){
 app.innerHTML = `<div class="shell"><aside class="side"><div class="brand"><img class="logo" src="logo.png?v=4" alt="Boombastic"/></div><nav class="nav" aria-label="Main navigation">${nav.map(([id,icon,label])=>`<button data-nav="${id}" class="${state.view===id?"active":""}"><span>${icon}</span>${label}</button>`).join("")}</nav><div class="side-promo"><b>♙ &nbsp; Boom Your Business!</b><p>Stay organized. Close more.<br/>Create unforgettable experiences.</p><button data-nav="reports">▥ &nbsp; View Reports</button></div><div class="side-footer">© 2025 Boombastic<br/>All rights reserved.</div></aside><header class="topbar"><h1>${state.view==="dashboard"?"Dashboard Overview":""}</h1><span class="bell">♧<i>3</i></span><span class="user-avatar">${initials(state.user?.name||"Admin User")}</span><b>${esc(state.user?.name||"Admin User")}</b><button id="logout" class="logout-button" title="Sign out" aria-label="Sign out">↪</button></header><main class="content">${content}</main></div>`;
 document.querySelectorAll("[data-nav]").forEach(b=>b.onclick=()=>{state.view=b.dataset.nav;render()}); const logoutButton=document.querySelector("#logout");if(logoutButton)logoutButton.onclick=logout;
}
function login(){
 app.innerHTML=`<div class="login"><div class="loginbox"><img class="logo logo-login" src="logo.png?v=4" alt="Boombastic"/><h1>Welcome Back</h1><p>Sign in to your Boombastic CRM workspace.</p><form id="auth"><div class="field"><label>Email</label><input id="email" type="email" required autocomplete="username" placeholder="you@company.com"/></div><div class="field"><label>Password</label><input id="password" type="password" required minlength="8" autocomplete="current-password" placeholder="Enter your password"/></div><div id="autherror" class="error" role="alert"></div><button class="btn primary" type="submit">Sign In</button></form></div></div>`;
 document.querySelector("#auth").onsubmit=async e=>{e.preventDefault();const submit=e.currentTarget.querySelector("button"),email=document.querySelector("#email").value,password=document.querySelector("#password").value,error=document.querySelector("#autherror");submit.disabled=true;submit.textContent="Signing in…";error.textContent="";try{const body=new URLSearchParams({username:email,password}),r=await fetch(API+"/auth/login",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body});if(!r.ok)throw new Error("Invalid email or password");const result=await r.json();state.token=result.access_token;localStorage.setItem("crm_token",state.token);state.user=await api("/auth/me");localStorage.setItem("crm_user",JSON.stringify(state.user));render()}catch(err){error.textContent=err.message;submit.disabled=false;submit.textContent="Sign In"}}}
function logout(){localStorage.removeItem("crm_token");localStorage.removeItem("crm_user");state.token=null;state.user=null;login()}
const quote = `<section class="quote"><div><b>👋 &nbsp; GOOD AFTERNOON, ${(state.user?.role||"admin").toUpperCase()}!</b><p>Let's turn every lead into an unforgettable celebration.</p></div><img src="logo.png?v=4" alt="Boombastic"/></section>`;
async function render(){if(!state.token)return login();try{if(state.view==="dashboard")return dashboard();if(state.view==="leads")return leads();if(state.view==="followups")return followups();if(state.view==="bookings")return bookings();if(state.view==="reports")return reports();if(state.view==="agreements")return agreements();return projects()}catch(e){shell(`<div class="empty">Could not load this workspace.<br/><small>${esc(e.message)}</small></div>`)}}
async function leads(){
 shell(quote+`<div id="leadbody"><div class="empty">Loading leads…</div></div>`);
 const qs=new URLSearchParams(Object.entries(state.filters).filter(([,v])=>v));
 const [data,a]=await Promise.all([api("/leads/?"+qs),api("/leads/analytics")]);state.leads=data.items;
 const today=state.leads.filter(l=>l.created_at&&new Date(l.created_at).toDateString()===new Date().toDateString()).length;
 const interested=(a.by_stage.interested||0), followups=(a.by_stage.call_back||0)+(a.by_stage.ringing||0), dead=(a.by_stage.lost||0)+(a.by_stage.not_interested||0);
 const cards=[["people",a.total,"TOTAL LEADS"],["calendar",today,"TODAY'S LEADS"],["clock",followups,"FOLLOW-UP"],["heart",interested,"INTERESTED"],["trophy",a.won,"CLOSED / WON"],["close",dead,"DEAD LEADS"]];
 const tableView=`<div class="table-wrap"><table class="leads-table"><thead><tr><th>Lead Name</th><th>Contact</th><th>Event Type</th><th>Source</th><th>Status</th><th>Follow-up</th><th>Assigned To</th><th>Action</th></tr></thead><tbody>${state.leads.length?state.leads.map(leadRow).join(""):`<tr><td colspan="8" class="empty">No leads match these filters.</td></tr>`}</tbody></table><footer class="table-footer"><span>Showing 1 to ${state.leads.length} of ${a.total} leads</span><div class="pagination"><b>1</b><span>2</span><span>3</span><span>…</span><span>›</span></div><label>Rows per page: <select><option>10</option><option>25</option></select></label></footer></div>`;
 const cardView=`<div class="lead-cards">${state.leads.length?state.leads.map(leadCard).join(""):`<div class="empty">No leads match these filters.</div>`}</div><footer class="cards-footer">Showing 1 to ${state.leads.length} of ${a.total} leads</footer>`;
 const body=document.querySelector("#leadbody");body.innerHTML=`<div class="kpi-row">${cards.map(([icon,n,label],i)=>`<div class="metric m${i}"><span class="metric-icon">${({people:"♙",calendar:"▣",clock:"◷",heart:"♡",trophy:"♕",close:"×"})[icon]}</span><div><b>${n}</b><small>${label}</small></div></div>`).join("")}</div><section class="leads-panel"><div class="leads-title"><h1>All Leads</h1><div class="view-switch" aria-label="Lead display"><button data-lead-view="table" class="${state.leadView==="table"?"active":""}" title="Table view">▤ <span>Table</span></button><button data-lead-view="cards" class="${state.leadView==="cards"?"active":""}" title="Card view">▦ <span>Cards</span></button></div></div><div class="filters"><label class="searchbox">⌕<input id="search" placeholder="Search leads by name, phone, or email..." value="${esc(state.filters.q)}"/></label><select id="source"><option value="">All Sources</option>${["manual_adding","meta","facebook","instagram","website","referral","event","outbound"].map(x=>`<option ${state.filters.source===x?"selected":""} value="${x}">${nice(x)}</option>`).join("")}</select><select id="event"><option>All Event Types</option><option>Walk-in</option><option>Birthday Party</option><option>Corporate Event</option><option>Kitty Party</option></select><select id="stage"><option value="">All Stages</option>${["new","contacted","interested","call_back","meeting_done","proposal_sent","on_hold","not_interested","won","lost","ringing"].map(x=>`<option ${state.filters.status===x?"selected":""} value="${x}">${nice(x)}</option>`).join("")}</select><button class="btn primary" id="addlead">＋ Add New Lead</button></div>${state.leadView==="cards"?cardView:tableView}</section>`;
 document.querySelector("#search").oninput=e=>filter("q",e.target.value);document.querySelector("#source").onchange=e=>filter("source",e.target.value);document.querySelector("#stage").onchange=e=>filter("status",e.target.value);
 document.querySelector("#addlead").onclick=leadModal;document.querySelectorAll("[data-detail]").forEach(b=>b.onclick=()=>leadDetail(b.dataset.detail));document.querySelectorAll("[data-lead-view]").forEach(b=>b.onclick=()=>{state.leadView=b.dataset.leadView;localStorage.setItem("crm_lead_view",state.leadView);leads()});
}
