function leadActions(l){return `<div class="row-actions"><a class="call" href="tel:${esc(l.phone||"")}" aria-label="Call ${esc(l.name)}" title="Call ${esc(l.name)}">${phoneIcon}</a><a class="whatsapp" href="https://wa.me/${String(l.phone||"").replace(/\D/g,"")}" target="_blank" rel="noreferrer" aria-label="WhatsApp ${esc(l.name)}" title="WhatsApp ${esc(l.name)}">${whatsappIcon}</a><button data-detail="${l._id}">◎ &nbsp; View</button></div>`}
function leadRow(l){const d=l.next_follow_up?new Date(l.next_follow_up):null;const date=d?d.toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"}):"—";const time=d?d.toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}):"—";const event=esc(l.service||l.campaign||"Birthday Party");return `<tr><td><div class="lead-name"><span class="avatar">${initials(l.name)}</span><div><b>${esc(l.name)}</b><small>${esc(l.email||"—")}</small></div></div></td><td><span class="contact">☎ &nbsp;${esc(l.phone||"No phone")}</span><small>✉ &nbsp;${esc(l.email||"—")}</small></td><td>♙ &nbsp; ${event}</td><td>${nice(l.source)}</td><td><span class="status ${l.status}">${nice(l.status==="call_back"?"Follow-up":l.status)}</span></td><td><span>▣ &nbsp;${date}</span><small>◷ &nbsp;${time}</small></td><td>${esc(l.assigned_to||"Admin User")}</td><td>${leadActions(l)}</td></tr>`}
function leadCard(l){const follow=l.next_follow_up?new Date(l.next_follow_up):null,created=l.created_at?new Date(l.created_at):null,event=l.service||l.project_name||"Event not selected",value=l.closed_amount?money(l.closed_amount):l.budget||"Value not added",source=nice(l.source||"other"),phone=String(l.phone||"").replace(/\D/g,"");return `<article class="lead-card lead-card-rich status-${l.status} temp-${l.temperature||"warm"}"><div class="lead-card-accent"></div><header><span class="avatar">${initials(l.name)}</span><div class="lead-card-title"><h3>${esc(l.name)}</h3><div class="lead-badges"><span class="status ${l.status}">${nice(l.status==="call_back"?"Follow-up":l.status)}</span><span class="source-badge">${source}</span><span class="temp-badge ${l.temperature||"warm"}">${nice(l.temperature||"warm")}</span></div></div></header><div class="lead-contact-lines"><span>☎ <b>${esc(l.phone||"No phone")}</b></span><span>✉ ${esc(l.email||"No email")}</span><span>⌖ ${esc(l.city||"City not added")}</span></div><div class="lead-card-tags"><span class="value-tag">${esc(value)}</span><span>▣ &nbsp;${esc(event)}</span>${l.timeline?`<span>◷ &nbsp;${esc(l.timeline)}</span>`:""}</div><p class="lead-origin">${esc(source)}${l.campaign?` — ${esc(l.campaign)}`:""}</p><div class="lead-card-meta"><span>◷ ${created?created.toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"2-digit"}):"Date unavailable"}</span><span class="assignee">${esc(l.assigned_to||"Unassigned")}</span>${follow?`<span class="follow-date">◷ ${follow.toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"2-digit"})}</span>`:""}</div><footer class="rich-card-actions"><a href="tel:${esc(l.phone||"")}">${phoneIcon}<span>Call</span></a><a class="whatsapp" href="https://wa.me/${phone}" target="_blank" rel="noreferrer">${whatsappIcon}<span>WhatsApp</span></a><button data-detail="${l._id}">◎ <span>Details</span></button></footer></article>`}
function modal(title,inner,submit){const box=document.createElement("div");box.className="modalback";box.innerHTML=`<div class="modal"><h2>${title}</h2><form id="modalform">${inner}<div class="modalfoot"><button type="button" class="btn" id="cancel">Cancel</button><button class="btn primary">Save</button></div></form></div>`;document.body.append(box);box.querySelector("#cancel").onclick=()=>box.remove();box.querySelector("#modalform").onsubmit=async e=>{e.preventDefault();try{await submit(new FormData(e.target));box.remove()}catch(err){say(err.message)}}}
