async function downloadLeadAttachment(leadId,file){const response=await fetch(`${API}/leads/${leadId}/attachments/${file._id}`,{headers:state.token?{Authorization:"Bearer "+state.token}:{}});if(!response.ok)throw new Error(apiMessage(await response.json().catch(()=>({detail:"Download failed"}))));const url=URL.createObjectURL(await response.blob()),link=document.createElement("a");link.href=url;link.download=file.filename;link.click();URL.revokeObjectURL(url)}
