function dashboardScope(all,period,from="",to=""){const now=new Date(),cutoff=new Date(now);if(period==="Custom Range")return dateRangeScope(all,from,to);if(period==="This Week"){const day=(now.getDay()+6)%7;cutoff.setDate(now.getDate()-day);cutoff.setHours(0,0,0,0)}else if(period==="This Month"){cutoff.setDate(1);cutoff.setHours(0,0,0,0)}else{cutoff.setMonth(0,1);cutoff.setHours(0,0,0,0)}return all.filter(l=>!l.created_at||new Date(l.created_at)>=cutoff)}
