async function followups(){const data=await api("/leads/?limit=100"),all=data.items||[],now=new Date(),dayStart=new Date(now.getFullYear(),now.getMonth(),now.getDate()),tomorrow=new Date(dayStart);tomorrow.setDate(tomorrow.getDate()+1);const scheduled=all.filter(l=>l.next_follow_up),due=scheduled.filter(l=>new Date(l.next_follow_up)>=dayStart&&new Date(l.next_follow_up)<tomorrow),overdue=scheduled.filter(l=>new Date(l.next_follow_up)<dayStart),upcoming=scheduled.filter(l=>new Date(l.next_follow_up)>=tomorrow),completed=all.filter(l=>["won","meeting_done"].includes(l.status)).length,rows=[...due,...upcoming,...overdue];shell(`<div class="follow-head"><div><h1>Follow-ups</h1><p>Stay on top of every conversation.</p></div></div><div class="follow-metrics">${[["▣",due.length,"DUE TODAY"],["◷",overdue.length,"OVERDUE"],["▤",upcoming.length,"UPCOMING"],["✓",completed,"COMPLETED"],["×",all.length-scheduled.length,"NO FOLLOW-UP"]].map(([i,n,t],x)=>`<div class="follow-metric fm${x}"><i>${i}</i><b>${n}</b><small>${t}</small></div>`).join("")}</div><section class="follow-panel"><div class="follow-toolbar"><div class="follow-tabs"><button class="active">Today</button><button>Upcoming</button><button>Overdue</button><button>Completed</button></div><label>⌕ <input id="follow-search" placeholder="Search by name, phone or event..."/></label><button class="btn primary" id="schedule-follow">＋ Schedule Follow-up</button></div><div class="follow-layout"><div class="follow-table-wrap"><table class="follow-table"><thead><tr><th>Customer</th><th>Contact</th><th>Event Type</th><th>Follow-up Date & Time</th><th>Assigned To</th><th>Priority</th><th>Action</th></tr></thead><tbody id="follow-rows">${rows.length?rows.map(followupRow).join(""):`<tr><td colspan="7" class="empty">No follow-ups scheduled.</td></tr>`}</tbody></table></div><aside class="schedule-side"><div class="mini-calendar"><header><b>${now.toLocaleDateString("en-US",{month:"long",year:"numeric"})}</b></header><div class="week">S M T W T F S</div><div class="days">${Array.from({length:35},(_,i)=>`<span class="${i+1===now.getDate()?"today":""}">${i<31?i+1:""}</span>`).join("")}</div></div><div class="today-list"><h3>Today's Schedule</h3>${due.slice(0,5).map(l=>`<div><time>${new Date(l.next_follow_up).toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"})}</time><span><b>${esc(l.name)}</b><small>${esc(l.service||"Follow-up")}</small></span></div>`).join("")||`<p class="empty">Nothing due today.</p>`}</div></aside></div></section>`);document.querySelector("#follow-search").oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll("#follow-rows tr").forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))};document.querySelector("#schedule-follow").onclick=()=>followupModal(all);document.querySelectorAll("[data-follow-done]").forEach(b=>b.onclick=async()=>{await api("/leads/"+b.dataset.followDone,{method:"PATCH",body:JSON.stringify({next_follow_up:null})});say("Follow-up completed");followups()});document.querySelectorAll("[data-follow-reschedule]").forEach(b=>b.onclick=()=>followupModal(all,b.dataset.followReschedule))}
function followupRow(l){const d=new Date(l.next_follow_up);return `<tr><td><div class="mini-contact"><span>${initials(l.name)}</span><b>${esc(l.name)}<small>${esc(l.phone||"—")}</small></b></div></td><td>${esc(l.phone||"—")}</td><td>${esc(l.service||l.campaign||"Event")}</td><td><b>${d.toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"})}</b><small>${d.toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"})}</small></td><td>${esc(l.assigned_to||"Admin User")}</td><td><span class="priority ${l.temperature||"warm"}">${nice(l.temperature||"warm")}</span></td><td><div class="follow-actions"><a href="tel:${esc(l.phone||"")}">☎ Call</a><a class="wa" href="https://wa.me/${String(l.phone||"").replace(/\D/g,"")}" target="_blank">WhatsApp</a><button data-follow-done="${l._id}">✓ Done</button><button data-follow-reschedule="${l._id}">▣ Reschedule</button></div></td></tr>`}
