async function bookings(){const [items,all]=await Promise.all([api("/meetings/"),api("/leads/?limit=100")]),leads=all.items||[];shell(`<div class="booking-head"><div class="booking-title-icon">▣</div><div><h1>Bookings</h1><p>Schedule, track & manage — online and offline</p></div><button class="btn primary" id="newitem">＋ Schedule Booking</button></div><div class="booking-tabs"><button data-booking-view="calendar" class="${state.bookingView==="calendar"?"active":""}">▣ &nbsp; Team Calendar</button><button data-booking-view="list" class="${state.bookingView==="list"?"active":""}">☷ &nbsp; List View</button></div><div id="booking-content">${state.bookingView==="calendar"?bookingCalendar(items,leads):bookingList(items,leads)}</div>`);document.querySelector("#newitem").onclick=()=>meetingModal(leads);document.querySelectorAll("[data-booking-view]").forEach(b=>b.onclick=()=>{state.bookingView=b.dataset.bookingView;localStorage.setItem("crm_booking_view",state.bookingView);bookings()});document.querySelectorAll("[data-edit-booking]").forEach(b=>b.onclick=()=>editMeetingModal(items.find(x=>x._id===b.dataset.editBooking),leads));document.querySelector("#booking-prev")?.addEventListener("click",()=>{state.bookingMonth--;if(state.bookingMonth<0){state.bookingMonth=11;state.bookingYear--}bookings()});document.querySelector("#booking-next")?.addEventListener("click",()=>{state.bookingMonth++;if(state.bookingMonth>11){state.bookingMonth=0;state.bookingYear++}bookings()});document.querySelector("#booking-today")?.addEventListener("click",()=>{const now=new Date();state.bookingMonth=now.getMonth();state.bookingYear=now.getFullYear();bookings()})}
function bookingCalendar(items,leads){const first=new Date(state.bookingYear,state.bookingMonth,1),days=new Date(state.bookingYear,state.bookingMonth+1,0).getDate(),offset=first.getDay(),today=new Date(),cells=Array.from({length:42},(_,index)=>{const day=index-offset+1;if(day<1||day>days)return `<div class="booking-day outside"></div>`;const events=items.filter(item=>{const date=new Date(item.scheduled_at);return date.getFullYear()===state.bookingYear&&date.getMonth()===state.bookingMonth&&date.getDate()===day}),isToday=today.getFullYear()===state.bookingYear&&today.getMonth()===state.bookingMonth&&today.getDate()===day;return `<div class="booking-day ${isToday?"today":""}"><b>${day}</b><div>${events.slice(0,3).map(event=>{const lead=leads.find(l=>l._id===event.lead_id),time=new Date(event.scheduled_at).toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"});return `<button class="calendar-event ${event.status}" data-edit-booking="${event._id}" title="${esc(event.title)}${lead?` — ${esc(lead.name)}`:""}"><time>${time}</time> ${esc(event.title)}</button>`}).join("")}${events.length>3?`<small>+${events.length-3} more</small>`:""}</div></div>`}).join("");return `<section class="booking-calendar"><header><h2>${first.toLocaleDateString("en-US",{month:"long",year:"numeric"})}</h2><div><button id="booking-prev" aria-label="Previous month">‹</button><button id="booking-today">Today</button><button id="booking-next" aria-label="Next month">›</button></div></header><div class="calendar-weekdays">${["SUN","MON","TUE","WED","THU","FRI","SAT"].map(x=>`<b>${x}</b>`).join("")}</div><div class="calendar-grid">${cells}</div></section>`}
function bookingList(items,leads){return `<div class="panel"><table class="table bookings-table"><thead><tr><th>When</th><th>Booking</th><th>Lead</th><th>Mode</th><th>Status</th><th>Action</th></tr></thead><tbody>${items.map(x=>`<tr><td>${new Date(x.scheduled_at).toLocaleString()}</td><td><b>${esc(x.title)}</b><br/><span class="meta">${x.duration_minutes} min</span></td><td>${esc(leads.find(l=>l._id===x.lead_id)?.name||"Unknown")}</td><td>${nice(x.mode)}</td><td><span class="chip ${x.status}">${nice(x.status)}</span></td><td><button class="edit-booking" data-edit-booking="${x._id}">✎ &nbsp; Edit</button></td></tr>`).join("")||`<tr><td colspan="6" class="empty">No bookings scheduled.</td></tr>`}</tbody></table></div>`}
