function sourceGradient(entries,colors){if(!entries.length)return "#ece8ef";const total=entries.reduce((sum,[,value])=>sum+value,0);let used=0;return `conic-gradient(${entries.map(([,value],i)=>{const start=used/total*100;used+=value;return `${colors[i%colors.length]} ${start}% ${used/total*100}%`}).join(",")})`}
const sourceChartObserver=new MutationObserver(()=>{const donut=document.querySelector(".source-donut"),rows=[...document.querySelectorAll(".source-body p")];if(!donut||!rows.length)return;let used=0;const segments=rows.map(row=>{const value=Number(row.querySelector("b")?.textContent.replace("%","")||0),color=getComputedStyle(row.querySelector("i")).backgroundColor,start=used;used+=value;return `${color} ${start}% ${used}%`});donut.style.background=rows.length===1?getComputedStyle(rows[0].querySelector("i")).backgroundColor:`conic-gradient(${segments.join(",")})`});sourceChartObserver.observe(app,{childList:true,subtree:true});
function renderReports(summary,all,meetings,proposals,team=""){const leads=team?all.filter(l=>(l.assigned_to||"Admin User")===team):all,leadIds=new Set(leads.map(l=>l._id)),teamProposals=proposals.filter(p=>leadIds.has(p.lead_id)),accepted=teamProposals.filter(p=>p.status==="accepted"),won=leads.filter(l=>l.status==="won"),qualified=leads.filter(l=>!["new","lost","not_interested"].includes(l.status)),revenue=accepted.reduce((n,p)=>n+Number(p.grand_total||p.amount||0),0),conversion=leads.length?Math.round(won.length/leads.length*100):0,avg=accepted.length?Math.round(revenue/accepted.length):0;const counts=xs=>xs.reduce((o,x)=>(o[x]=(o[x]||0)+1,o),{}),sources=counts(leads.map(l=>nice(l.source||"other"))),events=counts(leads.map(l=>l.service||l.campaign||"Other")),members=Object.values(leads.reduce((o,l)=>{const n=l.assigned_to||"Admin User";o[n]??={name:n,leads:0,follow:0,won:0,revenue:0};o[n].leads++;if(l.next_follow_up)o[n].follow++;if(l.status==="won")o[n].won++;o[n].revenue+=accepted.filter(p=>p.lead_id===l._id).reduce((sum,p)=>sum+Number(p.grand_total||p.amount||0),0);return o},{}));const sourceColors=["#7530c2","#367be3","#1cad9f","#f4a21a"],sourceEntries=Object.entries(sources).slice(0,4),sourceTotal=Math.max(sourceEntries.reduce((n,[,v])=>n+v,0),1),eventEntries=Object.entries(events).sort((a,b)=>b[1]-a[1]).slice(0,4),maxEvent=Math.max(...eventEntries.map(x=>x[1]),1),funnel=[["New",leads.length,"#7937c5"],["Contacted",leads.filter(l=>l.status!=="new").length,"#4b66db"],["Interested",qualified.length,"#1ca99c"],["Proposal",teamProposals.length,"#f2a126"],["Closed",won.length,"#ed3a47"]];const metrics=[["♙",leads.length,"TOTAL LEADS"],["▽",qualified.length,"QUALIFIED LEADS"],["♕",won.length,"BOOKINGS CLOSED"],["▥",conversion+"%","CONVERSION RATE"],["₹",money(revenue).replace("₹",""),"TOTAL REVENUE"],["▣",money(avg).replace("₹",""),"AVG. BOOKING VALUE"]];document.querySelector("#reports-body").innerHTML=`<div class="report-metrics">${metrics.map(([i,n,t],x)=>`<div class="report-metric rm${x}"><i>${i}</i><span><small>${t}</small><b>${n}</b></span></div>`).join("")}</div><div class="report-grid"><section class="report-card report-line"><h2>Leads & Conversions</h2><div class="report-legend">● Leads &nbsp;&nbsp; <i>● Bookings</i></div>${dashboardPerformanceChart(leads,meetings,"This Month")}</section><section class="report-card source-chart"><h2>Lead Sources</h2><div class="source-body"><div class="source-donut"></div><div>${sourceEntries.map(([n,v],i)=>`<p><i style="background:${sourceColors[i]}"></i><span>${n}</span><b>${Math.round(v/sourceTotal*100)}%</b></p>`).join("")||"No source data"}</div></div></section><section class="report-card event-chart"><h2>Event Type Performance</h2>${eventEntries.map(([n,v],i)=>`<div class="event-bar"><span>${esc(n)}</span><i><b style="width:${v/maxEvent*100}%"></b></i><strong>${v}</strong></div>`).join("")||`<p class="empty">No event data.</p>`}</section><section class="report-card revenue-chart"><h2>Revenue Summary</h2><div class="revenue-summary"><b>${money(revenue)}</b><span>from ${accepted.length} accepted proposal${accepted.length===1?"":"s"}</span><small>Only accepted proposal values are included.</small></div></section><section class="report-card team-report"><h2>Team Performance</h2><table><thead><tr><th>Team Member</th><th>Assigned Leads</th><th>Follow-ups</th><th>Bookings Closed</th><th>Revenue</th><th>Conversion</th></tr></thead><tbody>${members.map(m=>`<tr><td><span>${initials(m.name)}</span>${esc(m.name)}</td><td>${m.leads}</td><td>${m.follow}</td><td>${m.won}</td><td>${money(m.revenue)}</td><td><i><b style="width:${m.won/Math.max(m.leads,1)*100}%"></b></i>${Math.round(m.won/Math.max(m.leads,1)*100)}%</td></tr>`).join("")||`<tr><td colspan="6" class="empty">No team data.</td></tr>`}</tbody></table></section><section class="report-card funnel"><h2>Sales Funnel</h2>${funnel.map(([n,v,c],i)=>`<div style="--w:${100-i*13}%;--c:${c}"><span>${n}</span><b>${v}</b><small>${leads.length?Math.round(v/leads.length*100):0}%</small></div>`).join("")}</section></div>`}
function exportReport(all,team=""){const leads=team?all.filter(l=>(l.assigned_to||"Admin User")===team):all,rows=[["Lead","Phone","Email","Event","Source","Status","Assigned To","Follow-up"],...leads.map(l=>[l.name,l.phone,l.email,l.service,l.source,l.status,l.assigned_to,l.next_follow_up])],csv=rows.map(r=>r.map(v=>JSON.stringify(v||"")).join(",")).join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="boombastic-report.csv";a.click();URL.revokeObjectURL(a.href);say("Report exported")}
async function simpleList(kind,title,subtitle,columns){const [items,all]=await Promise.all([api("/"+kind+"/"),api("/leads/?limit=100")]);shell(`<div class=pagehead><div><h1>${title}</h1><p>${subtitle}</p></div></div><div class=panel><table class=table><thead><tr>${columns.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${items.map(x=>`<tr><td><b>${esc(x.title||x.name)}</b></td><td>${esc(all.items.find(l=>l._id===x.lead_id)?.name||"Unknown")}</td><td><span class="chip ${x.status}">${nice(x.status)}</span></td><td>${kind==="proposals"?money(x.grand_total):kind==="projects"?x.progress+"%":x.signed_at?new Date(x.signed_at).toLocaleDateString():"—"}</td></tr>`).join("")||`<tr><td colspan=4 class=empty>No ${title.toLowerCase()} yet.</td></tr>`}</tbody></table></div>`)}
const proposals=()=>simpleList("proposals","Proposals","Create commercial documents, track review and move deals forward.",["Proposal","Lead","Status","Total"]);
const agreements=()=>simpleList("agreements","Agreements","Track documents, signing state and commercial commitments.",["Agreement","Lead","Status","Signed"]);
const projects=()=>simpleList("projects","Projects & campaigns","Delivery visibility across every active client engagement.",["Project","Lead","Status","Progress"]);

// Revenue is recognized from Won leads and their saved pre-GST deal value.
const renderProposalBasedReports=renderReports;
renderReports=(summary,all,meetings,proposals,team="")=>{
 const scopedLeads=team?all.filter(l=>(l.assigned_to||"Admin User")===team):all;
 const wonDeals=scopedLeads.filter(l=>l.status==="won").map(l=>({lead_id:l._id,status:"accepted",grand_total:Number(l.closed_amount||0)}));
 renderProposalBasedReports(summary,all,meetings,wonDeals,team);
 const revenueCopy=document.querySelector(".revenue-summary");
 if(revenueCopy){
  const count=wonDeals.length;
  revenueCopy.querySelector("span").textContent=`from ${count} Won lead${count===1?"":"s"}`;
  revenueCopy.querySelector("small").textContent="Only deal values from leads marked Won are included (before GST).";
 }
 const leadIds=new Set(scopedLeads.map(l=>l._id)),proposalLeadIds=new Set(proposals.filter(p=>leadIds.has(p.lead_id)).map(p=>p.lead_id));
 const reached=(lead,status)=>lead.status===status||(lead.activities||[]).some(item=>item.type==="stage"&&String(item.message||"").toLowerCase()===`stage changed to ${status.replaceAll("_"," ")}`);
 const funnelCounts=[
  scopedLeads.length,
  scopedLeads.filter(l=>reached(l,"contacted")).length,
  scopedLeads.filter(l=>reached(l,"interested")).length,
  proposalLeadIds.size,
  scopedLeads.filter(l=>l.status==="won").length,
 ];
 [...document.querySelectorAll(".funnel > div")].forEach((step,index)=>{
  const value=funnelCounts[index]||0;
  step.querySelector("b").textContent=value;
  step.querySelector("small").textContent=(scopedLeads.length?Math.round(value/scopedLeads.length*100):0)+"%";
 });
};
render();
